            ("axial_crossing_12", crossing.as_slice(), true),
            (
                "ordinary_even2_8",
                [&a, &p[0], &p[1], &a, &p[2], &p[3], &p[4], &p[5]].as_slice(),
                false,
            ),
            (
                "ordinary_cyclic_12",
                [
                    &a, &p[0], &p[1], &p[2], &p[3], &p[4], &p[5], &p[6], &p[7], &p[8], &p[9], &a,
                ]
                .as_slice(),
                false,
            ),
        ] {
            let factors = axial
                .then(|| gamma5!())
                .into_iter()
                .chain(factors.iter().map(|p| gamma!(*p)));
            let input = trace!(&spin; factors);
            cases.push(Self {
                name: name.into(),
                expression: input.simplify_gamma(),
                gamma_input: Some(input),
                source: None,
            });
        }
        let external = g!(&a, &c)
            * g!(&b, &d)
            * trace!(&spin; [&a, &p[0], &b, &p[1], &p[2], &c, &p[3], &p[4], &d, &p[5], &p[6], &p[7]].map(|p| gamma!(p)));
        let free = trace!(&spin; (0..12).map(|i| gamma!(mink.pattern(symbol!(&format!("metric_benchmark::mu{i}"))))));
        for (name, input) in [("external_metrics_12", external), ("free_12", free)] {
            cases.push(Self {
                name: name.into(),
                expression: input.simplify_gamma(),
                gamma_input: Some(input),
                source: None,
            });
        }
        cases
    }
}

#[derive(Clone, Copy)]
enum Method {
    NormalizeDots,
    ParseOnly,
    ParseAndNormalizeDots,
    Repeated,
    MetricCore,
    GuardedMetricCore,
    MetricSettings,
    FullSchoonschip,
    EpsilonCleanup,
    FullGamma,
}
impl Method {
    const ALL: [Self; 10] = [
        Self::NormalizeDots,
        Self::ParseOnly,
        Self::ParseAndNormalizeDots,
        Self::Repeated,
        Self::MetricCore,
        Self::GuardedMetricCore,
        Self::MetricSettings,
        Self::FullSchoonschip,
        Self::EpsilonCleanup,
        Self::FullGamma,
    ];
    fn name(self) -> &'static str {
        match self {
            Self::NormalizeDots => "normalize_dots",
            Self::ParseOnly => "parse_only",
            Self::ParseAndNormalizeDots => "parse_and_normalize_dots",
            Self::Repeated => "repeated_indices_only",
            Self::MetricCore => "metric_contractor_only",
            Self::GuardedMetricCore => "guarded_metric_contractor",
            Self::MetricSettings => "metric_schoonschip",
            Self::FullSchoonschip => "full_schoonschip",
            Self::EpsilonCleanup => "epsilon_cleanup",
            Self::FullGamma => "full_gamma",
        }
    }
    fn input(self, case: &Case) -> Option<AtomView<'_>> {
        match self {
            Self::FullGamma => case.gamma_input.as_ref().map(Atom::as_view),
            Self::ParseOnly | Self::ParseAndNormalizeDots => {
                case.source.as_ref().map(|_| case.expression.as_view())
            }
            _ => Some(case.expression.as_view()),
        }
    }
    fn apply(self, expression: AtomView<'_>, source: Option<&str>) -> Atom {
        match self {
            Self::NormalizeDots => expression.normalize_dots(),
            Self::ParseOnly | Self::ParseAndNormalizeDots => {
                let parsed = Atom::parse(
                    source.unwrap(),
                    "spenso",
                    symbolica::parser::ParseSettings::symbolica(),
                )
                .unwrap();
                if matches!(self, Self::ParseOnly) {
                    parsed
                } else {
                    parsed.normalize_dots()
                }
            }
            Self::Repeated => Atom::num(i64::from(expression.has_repeated_explicit_indices())),
            Self::MetricCore => slot_contraction::SlotContraction::run(expression, true, false),
            Self::GuardedMetricCore => {
                if expression.has_repeated_explicit_indices() {
                    slot_contraction::SlotContraction::run(expression, true, false)
                } else {
                    expression.to_owned()
                }
            }
            Self::MetricSettings => expression.schoonschip_with_settings(
                &SchoonschipSettings::default()
                    .without_rank1_tensors()
                    .with_chain_like_functions(),
            ),
            Self::FullSchoonschip => expression.schoonschip_with_settings(
                &SchoonschipSettings::default().with_chain_like_functions(),
            ),
            Self::EpsilonCleanup => expression.simplify_epsilon(),
            Self::FullGamma => expression.simplify_gamma(),
        }
    }
    fn run(self, expression: AtomView<'_>, source: Option<&str>) {
        if matches!(self, Self::Repeated) {
            black_box(black_box(expression).has_repeated_explicit_indices());
        } else {
            let _ = black_box(self.apply(black_box(expression), black_box(source)));
        }
    }
    fn batch(self, expression: AtomView<'_>, source: Option<&str>, repetitions: usize) -> f64 {
        let started = Instant::now();
        for _ in 0..repetitions {
            self.run(expression, source);
        }
        started.elapsed().as_secs_f64() * 1e9 / repetitions as f64
    }
}

fn main() {
    let arguments: Vec<_> = std::env::args().collect();
    let directory = Path::new(arguments.get(1).expect(
        "usage: metric_contraction_benchmark OUTPUT_DIRECTORY [samples=5] [target_batch_ms=15]",
    ));
    let samples: usize = arguments.get(2).map_or(5, |s| s.parse().unwrap());
    let target_ms: f64 = arguments.get(3).map_or(15., |s| s.parse().unwrap());
    assert!(samples > 0 && target_ms.is_finite() && target_ms > 0.);
    std::fs::create_dir_all(directory).unwrap();
    idenso::representations::initialize();
    let _ = *idenso::epsilon::EPSILON_SYMBOL;
    for case in Case::cases() {
        if let Some(source) = &case.source {
            std::fs::write(directory.join(format!("{}.source", case.name)), source).unwrap();
        }
        std::fs::write(
            directory.join(format!("{}.input", case.name)),
            case.expression.to_plain_string(),
        )
        .unwrap();
        if let Some(input) = &case.gamma_input {
            std::fs::write(
                directory.join(format!("{}.gamma_input", case.name)),
                input.to_plain_string(),
            )
            .unwrap();
        }
        let methods: Vec<_> = Method::ALL
            .into_iter()
            .filter(|m| m.input(&case).is_some())
            .collect();
        let mut changed = Vec::new();
        let mut repetitions = Vec::new();
        let mut output_terms = Vec::new();
        for &method in &methods {
            let input = method.input(&case).unwrap();
            let output = method.apply(input, case.source.as_deref());
            changed.push(output.as_view() != input);
            output_terms.push(output.nterms());
            std::fs::write(
                directory.join(format!("{}.{}.output", case.name, method.name())),
                output.to_plain_string(),
            )
            .unwrap();
            if matches!(
                method,
                Method::NormalizeDots
                    | Method::MetricCore
                    | Method::GuardedMetricCore
                    | Method::MetricSettings
                    | Method::FullSchoonschip
                    | Method::EpsilonCleanup
            ) {
                assert_eq!(
                    method.apply(output.as_view(), None),
                    output,
                    "{} {} is not idempotent",
                    case.name,
                    method.name()
                );
            }
            let ns = method.batch(input, case.source.as_deref(), 1);
            repetitions.push((target_ms * 1e6 / ns).ceil().clamp(1., 500_000.) as usize);
        }
        let mut timings: Vec<Vec<f64>> = vec![Vec::new(); methods.len()];
        for sample in 0..samples {
            for offset in 0..methods.len() {
                let m = (sample + offset) % methods.len();
                timings[m].push(methods[m].batch(
                    methods[m].input(&case).unwrap(),
                    case.source.as_deref(),
                    repetitions[m],
                ));
            }
        }
        for (m, method) in methods.iter().enumerate() {
            let mut sorted = timings[m].clone();
            sorted.sort_by(f64::total_cmp);
            let median = if samples.is_multiple_of(2) {
                (sorted[samples / 2 - 1] + sorted[samples / 2]) / 2.
            } else {
                sorted[samples / 2]
            };
            println!(
                "{{\"case\":{:?},\"method\":{:?},\"terms\":{},\"output_terms\":{},\"changed\":{},\"repeated_indices\":{},\"repetitions\":{},\"samples_ns\":{:?},\"median_ns\":{median}}}",
                case.name,
                method.name(),
                method.input(&case).unwrap().nterms(),
                output_terms[m],
                changed[m],
                case.expression.has_repeated_explicit_indices(),
                repetitions[m],
                timings[m]
            );
        }
    }
}

aggregation_script:
"""Archive the matched registry/main comparison without altering earlier records."""

import difflib
import hashlib
import json
import math
import statistics
import tomllib
from pathlib import Path

ROOT = Path("/tmp/symbolica-main-update")
BASELINE = Path("/tmp/dot-normalization-improvements")
REPO = Path("/common/dev/gammaloop/feynkit-rich-display")
TARGET = REPO / "examples/notebooks/symbolica_main_update.json"
PREVIOUS = REPO / "examples/notebooks/dot_normalization.json"
REVISION = json.loads((ROOT / "final-revision.json").read_text())["final_main"]
DRIVER = "crates/idenso/examples/metric_contraction_benchmark.rs"


def read_json(path):
    return json.loads(path.read_text())


def read_rows(path):
    return [json.loads(line) for line in path.read_text().splitlines() if line.strip()]


def digest(path):
    with path.open("rb") as stream:
        return hashlib.file_digest(stream, "sha256").hexdigest()


def identity(path):
    return {"path": str(path), "sha256": digest(path), "bytes": path.stat().st_size}


def locks(directory):
    paths = [
        "Cargo.lock",
        "tydenso/Cargo.lock",
        "examples/notebooks/symbolica-host/Cargo.lock",
        "uv.lock",
    ]
    result = {}
    for name in paths:
        path = directory / name
        packages = tomllib.loads(path.read_text())["package"]
        selected = [
            p
            for p in packages
            if p["name"]
            in {"symbolica", "numerica", "graphica", "symjit", "symbolica-typst-atom-payload"}
        ]
        assert len([p for p in selected if p["name"] == "symbolica"]) == 1, name
        result[name] = {**identity(path), "selected_packages": selected}
    return result


def log_record(path):
    lines = path.read_text().splitlines()
    markers = [
        "Summary",
        "Finished",
        "FAIL [",
        "error:",
        "Nextest run ID",
        "Updated symbolica",
        "Resolved",
    ]
    return {
        **identity(path),
        "summary": [
            line for line in lines if any(marker in line for marker in markers)
        ],
    }


def source_change(before_path, after_path, name):
    result = {
        "before_sha256": digest(before_path),
        "after_sha256": digest(after_path),
        "before_bytes": before_path.stat().st_size,
        "after_bytes": after_path.stat().st_size,
    }
    contents = [path.read_bytes() for path in [before_path, after_path]]
    try:
        if any(b"\0" in content for content in contents):
            raise ValueError("Binary source")
        old, new = [content.decode("utf-8") for content in contents]
    except (UnicodeDecodeError, ValueError):
        result["scope"] = "Binary artifact identities only; payload omitted."
    else:
        result["patch"] = "".join(
            difflib.unified_diff(
                old.splitlines(keepends=True),
                new.splitlines(keepends=True),
                fromfile=f"before/{name}",
                tofile=f"after/{name}",
            )
        )
    return result


def main():
    prior = read_json(PREVIOUS)
    before = read_rows(ROOT / "fresh-baseline.jsonl")
    after = read_rows(ROOT / "after.jsonl")
    measurement = read_json(ROOT / "measurement.json")
    assert REVISION in json.dumps(measurement), "Measurement revision is not the final pin"
    assert [run["name"] for run in measurement["runs"]] == ["baseline", "main"]
    assert all(run["exit_code"] == 0 for run in measurement["runs"]), (
        "Matched benchmark pair did not complete successfully"
    )
    assert read_rows(BASELINE / "after.jsonl") == prior["after"], (
        "Historical registry samples changed"
    )
    semantic_fields = ("case", "method", "terms", "output_terms", "changed", "repeated_indices")
    assert [[row[field] for field in semantic_fields] for row in before] == [
        [row[field] for field in semantic_fields] for row in prior["after"]
    ], "Fresh registry run changed benchmark semantics"
    assert (REPO / DRIVER).read_text() == prior["benchmark_source_text"], (
        "Benchmark driver changed"
    )
    keyed = {
        phase: {(row["case"], row["method"]): row for row in rows}
        for phase, rows in [("before", before), ("after", after)]
    }
    assert (
        len(before) == len(after) == len(keyed["before"]) == len(keyed["after"]) == 641
    )
    assert keyed["before"].keys() == keyed["after"].keys()
    for rows in [before, after]:
        for row in rows:
            assert len(row["samples_ns"]) == 5
            assert all(
                math.isfinite(value) and value > 0 for value in row["samples_ns"]
            )
            assert math.isclose(
                statistics.median(row["samples_ns"]), row["median_ns"], rel_tol=1e-12
            )

    directories = {
        "before": ROOT / "fresh-baseline-output",
        "after": ROOT / "after-output",
    }
    snapshots = {
        phase: {path.name: digest(path) for path in sorted(directory.iterdir())}
        for phase, directory in directories.items()
    }
    assert snapshots["before"] == prior["output_sha256"]["after"]
    assert snapshots["before"].keys() == snapshots["after"].keys()
    differences = []
    for name, old_hash in snapshots["before"].items():
        if old_hash == snapshots["after"][name]:
            continue
        difference = {
            "name": name,
            "before_sha256": old_hash,
            "after_sha256": snapshots["after"][name],
        }
        for phase, directory in directories.items():
            path = directory / name
            if path.stat().st_size < 10000:
                difference[phase] = path.read_text()
        differences.append(difference)
    assert not any(row["name"].endswith(".source") for row in differences), (
        "Source inputs changed"
    )

    form_cases = {row["idenso_case"]: row for row in prior["form"]["records"]}
    comparison = []
    for key, old in keyed["before"].items():
        new = keyed["after"][key]
        case, method = key
        output_name = f"{case}.{method}.output"
        row = {
            "case": case,
            "method": method,
            "before_ms": old["median_ns"] / 1e6,
            "after_ms": new["median_ns"] / 1e6,
            "speedup": old["median_ns"] / new["median_ns"],
            "output_identical": snapshots["before"][output_name]
            == snapshots["after"][output_name],
        }
        if method == "full_gamma" and case in form_cases:
            form_ns = form_cases[case]["wall_ns_median"]
            row.update(
                form_wall_ms=form_ns / 1e6, after_over_form=new["median_ns"] / form_ns
            )
        comparison.append(row)

    before_metadata = read_json(ROOT / "before.json")
    revision_metadata = read_json(ROOT / "final-revision.json")
    assert before_metadata["main_revision"] == revision_metadata["previous_main"]
    assert REVISION == revision_metadata["final_main"]
    saved_sources = ROOT / "before-source"
    for name, checksum in before_metadata["source_sha256"].items():
        assert digest(saved_sources / name) == checksum, name
    saved_names = [
        str(path.relative_to(saved_sources))
        for path in sorted(saved_sources.rglob("*"))
        if path.is_file()
    ]
    after_locks = locks(REPO)
    for name, lock in after_locks.items():
        symbolica = next(
            p for p in lock["selected_packages"] if p["name"] == "symbolica"
        )
        source = symbolica["source"]
        source = source["git"] if isinstance(source, dict) else source
        assert f"?rev={REVISION}#{REVISION}" in source, (name, source)

    artifact_rows = read_rows(ROOT / "artifacts.jsonl")
    assert any(
        row.get("reason") == "build-finished" and row.get("success")
        for row in artifact_rows
    ), "Benchmark Cargo build did not report success"
    packages = {}
    relevant_names = {
        "symbolica",
        "symbolica_utils",
        "spenso",
        "idenso",
        "metric_contraction_benchmark",
    }
    for artifact in artifact_rows:
        if (
            artifact.get("reason") == "compiler-artifact"
            and artifact["target"]["name"] in relevant_names
        ):
            packages[artifact["target"]["name"]] = artifact
    assert all(
        name in packages
        for name in ["symbolica", "spenso", "idenso", "metric_contraction_benchmark"]
    )
    assert REVISION in packages["symbolica"]["package_id"]
    assert packages["metric_contraction_benchmark"]["executable"]
    old_executable = identity(BASELINE / "after")
    assert old_executable == prior["executable_identities"]["after"]
    new_executable = identity(ROOT / "after")
    emitted_executable = Path(packages["metric_contraction_benchmark"]["executable"])
    if emitted_executable.exists():
        assert digest(emitted_executable) == new_executable["sha256"], (
            "Built example no longer matches measured copy"
        )

    validation = {}
    final_runs_path = ROOT / "final-runs.json"
    final_runs = read_json(final_runs_path) if final_runs_path.exists() else []
    completed = {run["name"]: run for run in final_runs}
    expected_checks = {
        "workspace-without-doc-examples-check",
        "symbolica-utils-tests",
        "idenso-tests",
        "spenso-tests",
        "hep-tests",
        "clippy-idenso",
        "clippy-spenso",
        "clippy-hep",
    }
    for name in sorted(expected_checks):
        if name in completed:
            validation[name] = {**log_record(ROOT / f"{name}.log"), **completed[name]}
        else:
            validation[name] = {"status": "No completed command result recorded yet"}
    source_names = sorted(
        set(prior["after_source_sha256"]) | set(saved_names) | {DRIVER, "justfile"}
    )
    current_source_hashes = {
        name: digest(REPO / name) for name in source_names if (REPO / name).is_file()
    }
    measured_hashes_path = ROOT / "measured-source-sha256.json"
    if measured_hashes_path.exists():
        assert all(
            digest(REPO / name) == checksum
            for name, checksum in read_json(measured_hashes_path).items()
        )

    record = {
        "schema_version": 1,
        "date": "2026-09-24",
        "change": "Pin active Rust and Python Symbolica dependencies to the requested main revision; compare unchanged benchmark driver with the optimized registry-3.0.0 baseline.",
        "revision": {
            "repository": "https://github.com/symbolica-dev/symbolica",
            "commit": REVISION,
            "package_version": "3.0.0",
            "selection": "Updated main HEAD containing the user's upstream Wasm fix; immutable commit pinned",
        },
        "revision_update": revision_metadata,
        "baseline": {
            "description": "Final local-metric normalization and no-op visitor optimization with crates.io Symbolica 3.0.0.",
            "record": identity(PREVIOUS),
            "executable": old_executable,
            "metadata": before_metadata,
            "source_sha256": prior["after_source_sha256"],
            "locks": locks(saved_sources),
            "timing_provenance": "Fresh measurement of the exact archived registry executable, immediately before the main measurement. Historical timing samples remain unchanged in dot_normalization.json.",
            "fresh_semantics_and_snapshots_match_historical": True,
        },
        "timing_method": "Fresh sequential registry baseline then pinned main; five warm samples per method, rotating method order, adaptive batches targeting 8 ms, output destruction included. CPU 6 on a shared host. Our native validation/compiler group was suspended for both runs and resumed afterward; unrelated host load remains uncontrolled. API timings exclude initial parsing/construction; parse_only and parse_and_normalize_dots include it. Builds were not interleaved.",
        "measurement_run": measurement,
        "matrix": {
            "cases": len({row["case"] for row in before}),
            "rows_per_phase": len(before),
            "samples_per_row": 5,
        },
        "before": before,
        "after": after,
        "comparison": comparison,
        "gamma_comparison": [
            row for row in comparison if row["method"] == "full_gamma"
        ],
        "snapshots_sha256": snapshots,
        "snapshot_differences": differences,
        "snapshot_summary": {
            "total": len(snapshots["before"]),
            "different": len(differences),
            "identical": len(snapshots["before"]) - len(differences),
        },
        "snapshot_scope": "Plain-text source/input/output snapshot hashes; differing small outputs are embedded. Equality checks compare symbolic outputs, independently of binary atom serialization. Recreate complete snapshots by running the driver.",
        "form": {
            "provenance": "Reused unchanged FORM 5.0.0 measurements and programs from the preceding dot-normalization comparison; FORM was not rerun for this dependency update.",
            "source_record": identity(PREVIOUS),
            "measurements": prior["form"],
        },
        "atom_format": {
            "before": 0,
            "after": 1,
            "scope": "Symbolica atom export/import binary storage format, not the package version or printed expression syntax.",
            "compatibility": "This revision rejects legacy format-0 atom payloads. Export expressions as strings using the older version and parse them using the new version when migrating saved atom data.",
            "upstream_source": f"https://github.com/symbolica-dev/symbolica/blob/{REVISION}/src/atom/representation.rs",
        },
        "state_export_format": {
            "before": 5,
            "after": 6,
            "scope": "The outer Symbolica full state-export format, distinct from the inner Atom format flag.",
            "compatibility": "Payload validators and engine consumers must agree with this revision's outer export format. Plain-text benchmark equality does not validate runtime payload interoperability.",
            "upstream_source": f"https://github.com/symbolica-dev/symbolica/blob/{REVISION}/src/state.rs",
        },
        "after_locks": after_locks,
        "after_source_sha256": current_source_hashes,
        "source_changes": {
            name: source_change(saved_sources / name, REPO / name, name)
            for name in saved_names
            if (REPO / name).is_file()
            and digest(saved_sources / name) != digest(REPO / name)
        },
        "benchmark_source": DRIVER,
        "benchmark_source_text": (REPO / DRIVER).read_text(),
        "after_executable": new_executable,
        "build_artifacts": {
            "log": identity(ROOT / "artifacts.jsonl"),
            "selected_compiler_artifacts": packages,
        },
        "validation": validation,
        "native_validation_complete": expected_checks <= completed.keys(),
        "validation_complete": False,
        "integration_validation_status": "Blocked at production payload preflight: pinned atom-payload accepts outer Symbolica export version5, while pinned Symbolica emits6. Isolated candidate validation does not make the production pin compatible; tracked plugin assets retain their previous build.",
        "validation_scope": "final-runs.json is authoritative for completed final-revision native checks. Earlier checks and superseded main measurements remain scratch artifacts under initial-main and are not presented as final results.",
        "python_lock_validation": {
            name: log_record(ROOT / f"{name}.log")
            for name in ["uv-lock-fixed-main", "uv-lock-fixed-main-check"]
        },
        "reproduction": "taskset -c 6 cargo run --locked -p idenso --profile dev-optim --example metric_contraction_benchmark -- /tmp/symbolica-main-benchmark 5 8",
        "aggregation_script": Path(__file__).read_text(),
    }
    for name in [
        "final-runs",
        "measured-source-sha256",
        "isolation-guard-probes",
        "notebook-host-check",
        "tydenso-check",
        "snapshot-changes",
        "printer-snapshot-review",
        "upstream-wasm-fix-audit",
        "tydenso-adapter-fix",
        "exact-main-length-validation",
        "tydenso-assets-build",
        "tydenso-typst-checks",
        "initial-payload-runtime-failure",
        "initial-payload-tydenso-assets-build",
        "initial-payload-tydenso-typst-checks",
    ]:
        path = ROOT / f"{name}.json"
        if path.exists():
            record[name.replace("-", "_")] = read_json(path)
    payload_directory = ROOT / "tymbolica-interop"
    payload_patch = payload_directory / "payload-linked-format.patch"
    if payload_patch.exists():
        record["isolated_payload_candidate"] = {
            "status": "Upstream candidate only; not applied to the workspace dependency or tracked plugin assets.",
            "patch": {**identity(payload_patch), "contents": payload_patch.read_text()},
        }
        for name in ["patched-payload-tydenso-build", "patched-payload-tydenso-typst-checks"]:
            path = ROOT / f"{name}.json"
            if path.exists():
                certificate = read_json(path)
                if "payload_patch_sha256" in certificate:
                    assert certificate["payload_patch_sha256"] == digest(payload_patch)
                record["isolated_payload_candidate"][name.replace("-", "_")] = certificate
        candidate_script = ROOT / "check-patched-payload-tydenso-typst.py"
        if candidate_script.exists():
            record["isolated_payload_candidate"]["tydenso_check_script"] = {
                **identity(candidate_script), "contents": candidate_script.read_text()
            }
        candidate_validation = payload_directory / "payload-fix-validation.json"
        if candidate_validation.exists():
            certificate = read_json(candidate_validation)
            assert certificate["patch"]["sha256"] == digest(payload_patch)
            record["isolated_payload_candidate"]["payload_fix_validation"] = certificate
    payload_validation = payload_directory / "validation.json"
    if payload_validation.exists():
        record["production_payload_incompatibility"] = read_json(payload_validation)
    audit_path = Path("/tmp/symbolica-main-slot-audit/audit.json")
    if audit_path.exists():
        audit = read_json(audit_path)
        assert audit["main_commit"] in [REVISION, revision_metadata["previous_main"]]
        record["upstream_source_audit"] = {
            "identity": identity(audit_path),
            "audit": audit,
            "scope_note": "Read-only source audit of the initially selected main commit. The final revision includes the subsequent upstream Wasm serialization fix and is built, benchmarked and validated separately here.",
        }
    TARGET.write_text(json.dumps(record, indent=2) + "\n")
    print("Wrote", TARGET, record["matrix"], record["snapshot_summary"])
    for row in record["gamma_comparison"]:
        print(row["case"], row["before_ms"], row["after_ms"], row["speedup"])


if __name__ == "__main__":
    main()

